package org.joda.time;

import java.io.*;
import java.io.Serializable;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.Locale;
import org.joda.time.DateTimeFieldType;
import org.joda.time.base.AbstractPartial;
import org.joda.time.field.AbstractPartialFieldProperty;
import org.joda.time.field.FieldUtils;
import org.joda.time.format.DateTimeFormat;
import org.joda.time.format.DateTimeFormatter;
import org.joda.time.format.ISODateTimeFormat;
import org.joda.time.impl.DateTimeTypes.DayOfMonth;
import org.joda.time.impl.DateTimeTypes.HourOfDay;
import org.joda.time.impl.DateTimeTypes.Month;
import org.joda.time.impl.DateTimeTypes.Year;
import org.joda.time.impl.DateTimeTypes;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class Partial_Partial_TriageGen2Test {

    private final Chronology ISO = DateTimeChronology.getISODefault();

    @Test
    public void testConstructor_NullTypes() {
        try {
            new Partial(null, new int[]{2023}, ISO);
            fail("Expected IllegalArgumentException for null types");
        } catch (IllegalArgumentException e) {
            assertEquals("Types array must not be null", e.getMessage());
        }
    }

    @Test
    public void testConstructor_NullValues() {
        DateTimeFieldType[] types = {Year.yearOf};
        try {
            new Partial(types, null, ISO);
            fail("Expected IllegalArgumentException for null values");
        } catch (IllegalArgumentException e) {
            assertEquals("Values array must not be null", e.getMessage());
        }
    }

    @Test
    public void testConstructor_LengthMismatch() {
        DateTimeFieldType[] types = {Year.yearOf, Month.monthOfYear};
        int[] values = {2023};
        try {
            new Partial(types, values, ISO);
            fail("Expected IllegalArgumentException for length mismatch");
        } catch (IllegalArgumentException e) {
            assertEquals("Values array must be the same length as the types array", e.getMessage());
        }
    }

    @Test
    public void testConstructor_EmptyArrays() {
        DateTimeFieldType[] types = new DateTimeFieldType[0];
        int[] values = new int[0];
        Partial partial = new Partial(types, values, ISO);
        assertEquals(0, partial.size());
        assertEquals(0, partial.getValues().length);
    }

    @Test
    public void testConstructor_NullInTypesArray() {
        DateTimeFieldType[] types = {Year.yearOf, null};
        int[] values = {2023, 1};
        try {
            new Partial(types, values, ISO);
            fail("Expected IllegalArgumentException for null inside types array");
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("Types array must not contain null"));
        }
    }

    @Test
    public void testConstructor_WrongOrder() {
        // Month (smaller) followed by Year (larger) - should fail because it expects largest-to-smallest
        DateTimeFieldType[] types = {Month.monthOfYear, Year.yearOf};
        int[] values = {1, 2023};
        try {
            new Partial(types, values, ISO);
            fail("Expected IllegalArgumentException for wrong order");
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("Types array must be in order largest-smallest"));
        }
    }

    @Test
    public void testConstructor_DuplicateTypesNoRange() {
        // Using types that don't have range duration types to trigger the duplicate check
        DateTimeFieldType[] types = {Year.yearOf, Year.yearOf};
        int[] values = {2023, 2024};
        try {
            new Partial(types, values, ISO);
            fail("Expected IllegalArgumentException for duplicate types");
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("Types array must not contain duplicate"));
        }
    }

    @Test
    public void testConstructor_DuplicateTypesWithRangeMismatch() {
        // This tests the logic where range duration types are involved
        // Note: In Joda, most standard types have range types. 
        // If types are identical, they will likely trigger the duplicate check.
        DateTimeFieldType[] types = {Year.yearOf, Year.yearOf};
        int[] values = {2023, 2024};
        try {
            new Partial(types, values, ISO);
            fail("Expected IllegalArgumentException for duplicate types");
        } catch (IllegalArgumentException e) {
            assertTrue(e.getMessage().contains("Types array must not contain duplicate"));
        }
    }

    @Test
    public void testConstructor_ValidSequence() {
        DateTimeFieldType[] types = {Year.yearOf, Month.monthOfYear, DayOfMonth.dayOfMonthOf};
        int[] values = {2023, 5, 15};
        Partial partial = new Partial(types, values, ISO);

        assertEquals(3, partial.size());
        assertEquals(2023, partial.getValue(0));
        assertEquals(5, partial.getValue(1));
        assertEquals(15, partial.getValue(2));
        // Verify cloning
        values[0] = 9999;
        assertNotEquals(9999, partial.getValue(0));
    }

    @Test
    public void testConstructor_ValidationFailure() {
        // Chronology.validate will be called. Providing invalid month.
        DateTimeFieldType[] types = {Month.monthOfYear};
        int[] values = {13}; 
        try {
            new Partial(types, values, ISO);
            fail("Expected exception from chronology validation");
        } catch (IllegalArgumentException e) {
            // Joda throws IllegalArgumentException for invalid values during validation
        }
    }

    @Test
    public void testConstructor_ChronologyWithUTC() {
        DateTimeFieldType[] types = {Year.yearOf};
        int[] values = {2023};
        Partial partial = new Partial(types, values, ISO);
        // The constructor calls .withUTC() on the chronology
        assertTrue(partial.getChronology().isUTC());
    }
}
